with cleaned as (select id, store_id, status, channel, amount, shipping_fee, ceil(discount) discount_whole, coalesce(channel, 'N/A') resolved_channel from orders where order_date > date '2023-10-07' and store_id is not null), enriched as (select src.*, p.opened_date, p.city from cleaned src join stores p on src.store_id = p.id), cleaned_orders as (select id, status, channel, amount, shipping_fee, discount_whole, opened_date, city, coalesce(amount, 0) amount_filled from enriched where city is not null and amount < 590), enriched_orders as (select id, status, channel, amount, shipping_fee, discount_whole, opened_date, city, amount_filled, ntile(4) over (order by discount_whole, id) discount_whole_bucket, ntile(4) over w_ordered amount_bucket, lag(shipping_fee, 2) over (partition by channel, status order by amount_filled, id) prev_shipping_fee from cleaned_orders window w_ordered as (order by amount, id)) select id, status, channel, amount, shipping_fee, discount_whole, opened_date, city, amount_filled, discount_whole_bucket, amount_bucket, prev_shipping_fee, ntile(3) over (partition by status, city order by discount_whole desc, id) discount_whole_bucket_2, sum(discount_whole) over w_running cumulative_discount_whole from enriched_orders window w_running as (partition by city, channel order by amount, id rows between unbounded preceding and current row);
